    pub fn set(self: *Client, key: []const u8, value: []const u8, options: zstd.Cache.SetOptions) !u64 { const redis_key = try self.keyAlloc(key); defer self.allocator.free(redis_key); const ttl = try numberAlloc(self.allocator, options.ttl_ms orelse 0); defer self.allocator.free(ttl); const nx = if (options.only_if_absent) "1" else "0"; const script = "local e=redis.call('EXISTS',KEYS[1]); if ARGV[3]=='1' and e==1 then return redis.error_reply('CACHE_KEY_EXISTS') end; local v=redis.call('HINCRBY',KEYS[1],'version',1); redis.call('HSET',KEYS[1],'value',ARGV[1]); if ARGV[2]~='0' then local t=redis.call('TIME'); local x=t[1]*1000+math.floor(t[2]/1000)+tonumber(ARGV[2]); redis.call('HSET',KEYS[1],'expires',x); redis.call('PEXPIRE',KEYS[1],ARGV[2]); else redis.call('HSET',KEYS[1],'expires','') end; return v"; var response = self.command(&.{ "EVAL", script, "1", redis_key, value, ttl, nx }) catch |err| if (err == error.Redis_CACHE_KEY_EXISTS) return error.CacheKeyExists else return err; defer response.deinit(self.allocator); return intResponse(response); }
