    pub fn acquireLock(self: *Client, key: []const u8, token: []const u8, ttl_ms: u64) !zstd.Cache.Lock { const redis_key = try self.lockKeyAlloc(key); defer self.allocator.free(redis_key); const ttl = try numberAlloc(self.allocator, ttl_ms); defer self.allocator.free(ttl); var response = try self.command(&.{ "SET", redis_key, token, "NX", "PX", ttl }); defer response.deinit(self.allocator); switch (response) { .simple => {}, .bulk => |value| if (value == null) return error.LockUnavailable else {}, else => return error.LockUnavailable } return .{ .key = key, .token = token, .expires_at_ms = 0 }; }
