    pub fn allowRate(self: *Client, key: []const u8, limit: u64, window_ms: u64) !bool { if (limit == 0 or window_ms == 0) return error.InvalidRateLimit; const redis_key = try std.fmt.allocPrint(self.allocator, "{s}:rate:{s}", .{ self.options.namespace, key }); defer self.allocator.free(redis_key); const limit_text = try numberAlloc(self.allocator, limit); defer self.allocator.free(limit_text); const window = try numberAlloc(self.allocator, window_ms); defer self.allocator.free(window); const script = "local n=redis.call('INCR',KEYS[1]); if n==1 then redis.call('PEXPIRE',KEYS[1],ARGV[2]) end; if n<=tonumber(ARGV[1]) then return 1 else return 0 end"; var response = try self.command(&.{ "EVAL", script, "1", redis_key, limit_text, window }); defer response.deinit(self.allocator); return try intResponse(response) == 1; }
