    }
    pub fn ack(self: *Client, id: []const u8, consumer: []const u8) !void { const subject_end = std.mem.indexOfScalar(u8, id, '|') orelse return error.DeliveryNotFound; const stream = try self.streamKeyAlloc(id[0..subject_end]); defer self.allocator.free(stream); const message_id = id[subject_end + 1 ..]; const group = try std.fmt.allocPrint(self.allocator, "{s}:group", .{self.options.namespace}); defer self.allocator.free(group); const script = "local p=redis.call('XPENDING',KEYS[1],ARGV[1],ARGV[3],ARGV[3],1); if #p==0 or p[1][2]~=ARGV[2] then return 0 end; return redis.call('XACK',KEYS[1],ARGV[1],ARGV[3])"; var response = try self.command(&.{ "EVAL", script, "1", stream, group, consumer, message_id }); defer response.deinit(self.allocator); if (try intResponse(response) == 0) return error.DeliveryOwnershipLost; }
