    fn command(self: *Client, args: []const []const u8) !Resp { const address = std.Io.net.IpAddress.resolve(self.io, self.options.host, self.options.port) catch return error.RedisUnavailable; var stream = address.connect(self.io, .{ .mode = .stream }) catch return error.RedisUnavailable; defer stream.close(self.io); try self.authenticate(stream); const request = try encodeCommandAlloc(self.allocator, args); defer self.allocator.free(request); try writeAll(stream, self.io, request); return readResp(self.allocator, stream, self.io, self.options.max_reply_bytes); }
    fn authenticate(self: *Client, stream: std.Io.net.Stream) !void { if (self.options.password) |password| { const auth = try encodeCommandAlloc(self.allocator, &.{ "AUTH", password }); defer self.allocator.free(auth); try writeAll(stream, self.io, auth); var authenticated = try readResp(self.allocator, stream, self.io, self.options.max_reply_bytes); defer authenticated.deinit(self.allocator); _ = try stringResponse(authenticated); } }
    fn keyAlloc(self: *Client, key: []const u8) ![]u8 { if (key.len == 0 or key.len > 1024) return error.InvalidCacheKey; return std.fmt.allocPrint(self.allocator, "{s}:cache:{s}", .{ self.options.namespace, key }); }
    fn lockKeyAlloc(self: *Client, key: []const u8) ![]u8 { if (key.len == 0 or key.len > 1024) return error.InvalidCacheKey; return std.fmt.allocPrint(self.allocator, "{s}:lock:{s}", .{ self.options.namespace, key }); }
    fn streamKeyAlloc(self: *Client, subject: []const u8) ![]u8 { if (subject.len == 0 or subject.len > 512) return error.InvalidMessage; return std.fmt.allocPrint(self.allocator, "{s}:stream:{s}", .{ self.options.namespace, subject }); }
