fn intResponse(response: Resp) !u64 { return switch (response) { .integer => |value| if (value < 0) error.InvalidRedisReply else @intCast(value), else => error.InvalidRedisReply }; }
fn stringResponse(response: Resp) ![]const u8 { return switch (response) { .bulk => |value| value orelse error.InvalidRedisReply, .simple => |value| value, else => error.InvalidRedisReply }; }
fn streamSequence(id: []const u8) !u64 { const dash = std.mem.indexOfScalar(u8, id, '-') orelse return error.InvalidRedisReply; return std.fmt.parseUnsigned(u64, id[0..dash], 10); }
fn deliveryFromAutoClaimAlloc(allocator: std.mem.Allocator, subject: []const u8, response: Resp) !?zstd.Broker.Delivery { const root = switch (response) { .array => |value| value, else => return error.InvalidRedisReply }; if (root.len < 2) return error.InvalidRedisReply; const messages = switch (root[1]) { .array => |value| value, else => return error.InvalidRedisReply }; if (messages.len == 0) return null; return try deliveryFromMessageAlloc(allocator, subject, messages[0], 2); }
fn deliveryFromReadAlloc(allocator: std.mem.Allocator, subject: []const u8, response: Resp, attempt: u32) !?zstd.Broker.Delivery { const root = switch (response) { .array => |value| value, .bulk => return null, else => return error.InvalidRedisReply }; if (root.len == 0) return null; const stream_record = switch (root[0]) { .array => |value| value, else => return error.InvalidRedisReply }; if (stream_record.len != 2) return error.InvalidRedisReply; const messages = switch (stream_record[1]) { .array => |value| value, else => return error.InvalidRedisReply }; if (messages.len == 0) return null; return try deliveryFromMessageAlloc(allocator, subject, messages[0], attempt); }
fn deliveryFromMessageAlloc(allocator: std.mem.Allocator, subject: []const u8, response: Resp, default_attempt: u32) !zstd.Broker.Delivery { const record = switch (response) { .array => |value| value, else => return error.InvalidRedisReply }; if (record.len != 2) return error.InvalidRedisReply; const redis_id = try stringResponse(record[0]); const fields = switch (record[1]) { .array => |value| value, else => return error.InvalidRedisReply }; var payload: ?[]const u8 = null; var key: ?[]const u8 = null; var attempt = default_attempt; var index: usize = 0; while (index + 1 < fields.len) : (index += 2) { const name = try stringResponse(fields[index]); const value = try stringResponse(fields[index + 1]); if (std.mem.eql(u8, name, "payload")) payload = value else if (std.mem.eql(u8, name, "key")) key = value else if (std.mem.eql(u8, name, "attempt")) attempt = std.fmt.parseUnsigned(u32, value, 10) catch return error.InvalidRedisReply; } const opaque_id = try std.fmt.allocPrint(allocator, "{s}|{s}", .{ subject, redis_id }); errdefer allocator.free(opaque_id); const owned_subject = try allocator.dupe(u8, subject); errdefer allocator.free(owned_subject); const owned_payload = try allocator.dupe(u8, payload orelse return error.InvalidRedisReply); errdefer allocator.free(owned_payload); const owned_key = try allocator.dupe(u8, key orelse return error.InvalidRedisReply); return .{ .allocator = allocator, .id = opaque_id, .subject = owned_subject, .payload = owned_payload, .idempotency_key = owned_key, .attempt = attempt }; }
fn numberAlloc(allocator: std.mem.Allocator, value: u64) ![]u8 { return std.fmt.allocPrint(allocator, "{d}", .{value}); }
fn encodeCommandAlloc(allocator: std.mem.Allocator, args: []const []const u8) ![]u8 { var output = std.ArrayList(u8).empty; errdefer output.deinit(allocator); try output.print(allocator, "*{d}\r\n", .{args.len}); for (args) |arg| try output.print(allocator, "${d}\r\n{s}\r\n", .{ arg.len, arg }); return output.toOwnedSlice(allocator); }
fn readResp(allocator: std.mem.Allocator, stream: std.Io.net.Stream, io: std.Io, max: usize) !Resp { const prefix = try readByte(stream, io); return switch (prefix) { '+' => .{ .simple = try readLineAlloc(allocator, stream, io, max) }, '-' => { const message = try readLineAlloc(allocator, stream, io, 1024); defer allocator.free(message); if (std.mem.indexOf(u8, message, "CACHE_KEY_EXISTS") != null) return error.Redis_CACHE_KEY_EXISTS; if (std.mem.indexOf(u8, message, "CACHE_VERSION_CONFLICT") != null) return error.Redis_CACHE_VERSION_CONFLICT; if (std.mem.indexOf(u8, message, "BUSYGROUP") != null) return error.Redis_BUSY_GROUP; return error.RedisCommandFailed; }, ':' => blk: { const line = try readLineAlloc(allocator, stream, io, 64); defer allocator.free(line); break :blk .{ .integer = try std.fmt.parseInt(i64, line, 10) }; }, '$' => blk: { const line = try readLineAlloc(allocator, stream, io, 64); defer allocator.free(line); const length = try std.fmt.parseInt(i64, line, 10); if (length == -1) break :blk .{ .bulk = null }; if (length < 0 or length > max) return error.RedisReplyTooLarge; const bytes = try allocator.alloc(u8, @intCast(length)); errdefer allocator.free(bytes); try readExact(stream, io, bytes); try expectCrlf(stream, io); break :blk .{ .bulk = bytes }; }, '*' => blk: { const line = try readLineAlloc(allocator, stream, io, 64); defer allocator.free(line); const count = try std.fmt.parseInt(i64, line, 10); if (count == -1) break :blk .{ .bulk = null }; if (count < 0 or count > 1024) return error.InvalidRedisReply; const values = try allocator.alloc(Resp, @intCast(count)); errdefer allocator.free(values); var initialized: usize = 0; errdefer for (values[0..initialized]) |*value| value.deinit(allocator); for (values) |*value| { value.* = try readResp(allocator, stream, io, max); initialized += 1; } break :blk .{ .array = values }; }, else => error.InvalidRedisReply }; }
fn readLineAlloc(allocator: std.mem.Allocator, stream: std.Io.net.Stream, io: std.Io, max: usize) ![]u8 { var output = std.ArrayList(u8).empty; errdefer output.deinit(allocator); while (output.items.len <= max) { const byte = try readByte(stream, io); if (byte == '\r') { if (try readByte(stream, io) != '\n') return error.InvalidRedisReply; return output.toOwnedSlice(allocator); } try output.append(allocator, byte); } return error.RedisReplyTooLarge; }
fn readByte(stream: std.Io.net.Stream, io: std.Io) !u8 { var buffer: [1]u8 = undefined; const count = try readSome(stream, io, &buffer); if (count == 0) return error.EndOfStream; return buffer[0]; }
fn readExact(stream: std.Io.net.Stream, io: std.Io, buffer: []u8) !void { var offset: usize = 0; while (offset < buffer.len) { const count = try readSome(stream, io, buffer[offset..]); if (count == 0) return error.EndOfStream; offset += count; } }
fn expectCrlf(stream: std.Io.net.Stream, io: std.Io) !void { if (try readByte(stream, io) != '\r' or try readByte(stream, io) != '\n') return error.InvalidRedisReply; }
fn readSome(stream: std.Io.net.Stream, io: std.Io, buffer: []u8) !usize { var parts = [_][]u8{buffer}; return io.vtable.netRead(io.userdata, stream.socket.handle, &parts); }
fn writeAll(stream: std.Io.net.Stream, io: std.Io, bytes: []const u8) !void { var offset: usize = 0; while (offset < bytes.len) { const parts = [_][]const u8{bytes[offset..]}; const count = try io.vtable.netWrite(io.userdata, stream.socket.handle, "", &parts, 1); if (count == 0) return error.WriteZero; offset += count; } }
test "RESP command encoding is binary safe" { const encoded = try encodeCommandAlloc(std.testing.allocator, &.{ "SET", "key", "hello\r\nworld" }); defer std.testing.allocator.free(encoded); try std.testing.expectEqualStrings("*3\r\n$3\r\nSET\r\n$3\r\nkey\r\n$12\r\nhello\r\nworld\r\n", encoded); }
